<script setup lang="ts">
import { computed } from 'vue'
import { ArrowRight, Clock3, FileCheck, Package, ShoppingBag } from 'lucide-vue-next'
import { useCompanyData } from '@/composables/useCompanyData'
import { orderStatuses, type OrderStatus } from '@/types/print-orders'
import { formatTime } from '@/services/printFiles'
import ArtStatsCard from './art/ArtStatsCard.vue'
const { orders, customers } = useCompanyData()
const counts = computed(() => ({ total:orders.value.length, waiting:orders.value.filter(o=>o.status === 'awaiting_design').length, review:orders.value.filter(o=>o.status === 'pending_review').length, production:orders.value.filter(o=>o.status === 'producing').length }))
const activity = computed(()=>orders.value.flatMap(o=>o.history.map(item=>({...item,orderId:o.id,title:o.title}))).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,6))
const pending = computed(()=>orders.value.filter(o=>['pending_review','approved','awaiting_design','needs_revision'].includes(o.status)).slice(0,5))
</script>
<template><section><div class="company-page-heading"><div><p>PRINT OPERATIONS</p><h1>让每一笔定制，有序发生。</h1><span>设计有进度，生产有依据，交付有记录。</span></div><RouterLink class="company-primary" to="/company/orders">管理订单<ArrowRight :size="16"/></RouterLink></div><div class="company-stats-grid"><RouterLink to="/company/orders"><ArtStatsCard title="全部订单" :count="counts.total" :icon="ShoppingBag" :description="`${customers.length} 位客户的定制需求`"/></RouterLink><RouterLink to="/company/orders?status=awaiting_design"><ArtStatsCard title="等待客户设计" :count="counts.waiting" :icon="Clock3" description="分享链接邀请客户 DIY" tone="amber"/></RouterLink><RouterLink to="/company/orders?status=pending_review"><ArtStatsCard title="印花待审核" :count="counts.review" :icon="FileCheck" description="核对图稿后即可安排生产" tone="blue"/></RouterLink><RouterLink to="/company/orders?status=producing"><ArtStatsCard title="生产中" :count="counts.production" :icon="Package" description="按确认的印花版本生产" tone="purple"/></RouterLink></div><div class="company-overview-grid"><section class="company-panel"><div class="art-table-header"><h2>待办订单</h2><RouterLink class="company-text-button" to="/company/orders">查看全部<ArrowRight :size="14"/></RouterLink></div><div class="company-todo-list"><RouterLink v-for="o in pending" :key="o.id" :to="`/company/orders?order=${o.id}`"><span class="company-todo-icon"><Package :size="18"/></span><div><b>{{ o.title }}</b><small>{{ o.id }} · {{ o.quantity }} 件</small></div><span class="company-status" :class="o.status">{{ orderStatuses[o.status as OrderStatus] }}</span><ArrowRight :size="14"/></RouterLink><p v-if="!pending.length" class="company-empty-copy">暂时没有待办订单。</p></div></section><section class="company-panel"><div class="art-table-header"><h2>最近动态</h2><span class="company-cell-muted">按实际操作更新</span></div><ol class="company-activity-list"><li v-for="item in activity" :key="item.id"><i></i><div><b>{{ item.text }}</b><RouterLink :to="`/company/orders?order=${item.orderId}`">{{ item.title }}</RouterLink><small>{{ formatTime(item.at) }} · {{ item.actor }}</small></div></li></ol></section></div><section class="company-process-strip"><h3>一条清晰的交付路径</h3><div><span><b>01</b>建立订单</span><ArrowRight :size="15"/><span><b>02</b>分享客户设计入口</span><ArrowRight :size="15"/><span><b>03</b>审核印花</span><ArrowRight :size="15"/><span><b>04</b>生产与发货</span></div></section></section></template>
